import{_ as r,C as s,o as d,c as o,a3 as p,E as n,w as i,a as l,j as e}from"./chunks/framework.D3kUw6rp.js";const c="/assets/image.gZn32xBW.png",g="/assets/image-black.BQsgx3pe.png",x="/assets/image-white.Dqt-7AK5.png",h="/assets/tool.BJDpkFY8.png",N=JSON.parse('{"title":"一张图片显示两种内容","description":"","frontmatter":{},"headers":[],"relativePath":"article/2025/black-white/index.md","filePath":"article/2025/black-white/index.md"}'),m={name:"article/2025/black-white/index.md"};function u(y,t,_,b,f,P){const a=s("center");return d(),o("div",null,[t[2]||(t[2]=p('<h1 id="一张图片显示两种内容" tabindex="-1">一张图片显示两种内容 <a class="header-anchor" href="#一张图片显示两种内容" aria-label="Permalink to &quot;一张图片显示两种内容&quot;">​</a></h1><p>本文将介绍在一张图片中显示两种内容的原理，以及推荐一款我写的<a href="./../../../tools/black-white/">网页小工具</a>，让你快速制作一张类似的图片。</p><p>在看文章的你，不妨试着修改下当前博客的主题色，切换一下明暗主题，即可看到下面的图片内容发生变化。</p><p><img src="'+c+'" alt=""></p><p>这种图片内容切换生效的前提条件是：</p><ul><li>图片存储格式为 PNG</li><li>查看图片的背景是纯白或纯黑</li></ul><h2 id="「均匀地」抠图" tabindex="-1">「均匀地」抠图 <a class="header-anchor" href="#「均匀地」抠图" aria-label="Permalink to &quot;「均匀地」抠图&quot;">​</a></h2><p>我们都知道图片格式有 PNG、JPEG、webP 等，但 PNG 可以保存图片的透明部分，我们也是利用它可以保留透明部分的特性，来实现一张图片塞下两张图片的内容。另外这里也利用了人类视觉天生具有弥补和联想能力的特性，在一张几千甚至上万个像素点的图片中，我们把它的像素点「均匀地」抠掉一半，基本不会影响整体观感。</p><p>这就类似小时候特别流行的小瓷砖拼接马赛克图案，如果瓷砖足够小、墙壁足够大，远看过去图片还是很「清晰的」。</p><p>所以我们可以选择两张图片：</p><ul><li>对于图片一，抠掉奇数行的偶数列，和偶数行的奇数列像素；</li><li>对于图片二，抠掉奇数行的奇数列，和偶数行的偶数列像素；</li></ul><p>然后将两张图片重叠成一张图片。这个过程用表格大概模拟一下就是（下图 1 表示显示图片 1 的像素、2 表示显示图片 2 的像素）：</p><table tabindex="0"><thead><tr><th style="text-align:center;">1</th><th style="text-align:center;">2</th><th style="text-align:center;">1</th><th style="text-align:center;">2</th><th style="text-align:center;">1</th><th style="text-align:center;">2</th><th style="text-align:center;">1</th></tr></thead><tbody><tr><td style="text-align:center;">2</td><td style="text-align:center;">1</td><td style="text-align:center;">2</td><td style="text-align:center;">1</td><td style="text-align:center;">2</td><td style="text-align:center;">1</td><td style="text-align:center;">2</td></tr><tr><td style="text-align:center;">1</td><td style="text-align:center;">2</td><td style="text-align:center;">1</td><td style="text-align:center;">2</td><td style="text-align:center;">1</td><td style="text-align:center;">2</td><td style="text-align:center;">1</td></tr></tbody></table><p>这样我们就得到了一张混合了两张图片像素的图片，虽然没有那么精细——毕竟每张图片我们只取了一半的像素过来，但不影响最终视觉观感。</p><p>接下来要做的就是如何：</p><ul><li>在白色背景下只显示图片 1</li><li>在黑色背景下只显示图片 2</li></ul><p>这样才能达到我们切换黑白背景时，同一张图片显示不同内容的目的。</p><h2 id="调整-png-参数" tabindex="-1">调整 PNG 参数 <a class="header-anchor" href="#调整-png-参数" aria-label="Permalink to &quot;调整 PNG 参数&quot;">​</a></h2><p>PNG 的像素数据一般由「红 R、绿 G、蓝 B、透明 A」 组成，接下来我们只要把 RGB 改成全部 255 或者 0，就能显示全白或者全黑的图片。在这个基础上通过设置透明度 A，让该像素具备不同的明暗度，就能显示图片的黑白效果。</p><p>换句话说，假设背景是白色的时候，有一张<code>黑白偏白</code>的图片是看不见的；而当背景是黑色的时候，<code>黑白偏黑</code>的那张图片则是看不见的。</p><p>现在很多平台比如少数派都有主题切换的功能，刚好具备在白色和黑色之间做切换的能力。所以我们就可以做一张融合了两张黑白图片的图片，来达到主题变化带动图片变化的效果。</p><p><img src="'+g+'" alt=""></p>',22)),n(a,null,{default:i(()=>[...t[0]||(t[0]=[l("暗色主题看到的是这张图",-1)])]),_:1}),t[3]||(t[3]=e("p",null,[e("img",{src:x,alt:""})],-1)),n(a,null,{default:i(()=>[...t[1]||(t[1]=[l("亮色主题看到的是这张图",-1)])]),_:1}),t[4]||(t[4]=e("h2",{id:"快速制作",tabindex:"-1"},[l("快速制作 "),e("a",{class:"header-anchor",href:"#快速制作","aria-label":'Permalink to "快速制作"'},"​")],-1)),t[5]||(t[5]=e("p",null,[l("如果你觉得这样的小巧思比较有意思，也想做一张这样的图，那么我也写了一个"),e("a",{href:"./../../../tools/black-white/"},"小工具"),l("供你使用。")],-1)),t[6]||(t[6]=e("p",null,[e("img",{src:h,alt:""})],-1))])}const w=r(m,[["render",u]]);export{N as __pageData,w as default};
